<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rechnungstool</title>
<style>
body{font-family:system-ui,Segoe UI,Arial,sans-serif;background:#f3f6fa;margin:0;color:#172033}.page{max-width:1700px;margin:auto;padding:26px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.top h1{margin:0;font-size:26px}.subtitle{color:#667085;margin-top:4px}.toolbar{display:grid;grid-template-columns:repeat(6,minmax(130px,1fr));gap:12px;background:#fff;border:1px solid #e1e6ef;border-radius:14px;padding:16px;box-shadow:0 4px 16px #1f29370b}.field{display:flex;flex-direction:column;gap:5px;font-size:12px;color:#667085}.field input,.field select{font:inherit;padding:9px 10px;border:1px solid #ccd3df;border-radius:8px;background:#fff;color:#172033}.toolbar .actions{display:flex;align-items:end}.primary{width:100%;padding:10px 14px;border:0;border-radius:8px;background:#1f4f8a;color:#fff;font-weight:650;cursor:pointer}.notice{margin:14px 0;padding:10px 12px;border-radius:9px;background:#eef5ff;color:#27415f;border:1px solid #d5e6ff}.workspace{display:grid;grid-template-columns:minmax(650px,1.25fr) minmax(450px,.75fr);gap:16px;margin-top:16px;align-items:start}.card{background:#fff;border:1px solid #e1e6ef;border-radius:14px;box-shadow:0 4px 16px #1f293708;overflow:hidden}.card-head{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid #edf0f5}.card-head h2{margin:0;font-size:17px}.badge{background:#eef2f7;border-radius:999px;padding:4px 9px;font-size:12px;color:#526071}.list{max-height:68vh;overflow:auto}.order{display:grid;grid-template-columns:90px 1fr 110px;gap:10px;padding:12px 14px;border-bottom:1px solid #edf0f5;text-decoration:none;color:inherit}.order:hover{background:#f7faff}.order.selected{background:#eef5ff}.orderno{font-weight:700}.name{font-weight:650}.desc{font-size:13px;color:#667085;margin-top:3px}.date{text-align:right;font-size:12px;color:#667085}.detail{padding:16px}.detail h2{margin:0 0 6px}.detail .muted{color:#667085}.position{padding:12px 0;border-top:1px solid #edf0f5}.position:first-of-type{border-top:0}.pos-title{font-weight:650}.metrics{display:flex;gap:14px;flex-wrap:wrap;margin-top:6px;font-size:12px;color:#667085}.warning{background:#fff5db;border:1px solid #efd48b;border-radius:8px;padding:9px;margin:10px 0}.empty{padding:40px 20px;text-align:center;color:#667085}.back{color:#475467;text-decoration:none}@media(max-width:1100px){.toolbar{grid-template-columns:repeat(2,1fr)}.workspace{grid-template-columns:1fr}.list{max-height:none}}
</style></head><body><div class="page"><div class="top"><div><h1>Rechnungstool</h1><div class="subtitle">Vorschau und Testlauf · angemeldet als {{ $adUsername ?: 'unbekannt' }}</div></div><a class="back" href="{{ route('dashboard') }}">← Hauptmenü</a></div>
<div class="notice"><strong>Phase 1:</strong> vollständig lesend. Es werden keine Rechnungen erzeugt und keine Abrechnungsdaten verändert.</div>
<form method="get" class="toolbar"><label class="field">Von<input type="date" name="von" value="{{ $von }}"></label><label class="field">Bis<input type="date" name="bis" value="{{ $bis }}"></label><label class="field">Abrechnungsart<select name="art"><option value="nachtraeglich" @selected($art==='nachtraeglich')>Nachträglich</option><option value="voraus" @selected($art==='voraus')>Im Voraus</option><option value="domain" @selected($art==='domain')>Domains</option></select></label><label class="field">Auftrag<input type="number" min="0" name="auftragsnr" value="{{ $auftragsnr?:'' }}" placeholder="alle"></label><label class="field">Kunde / Text<input type="text" name="q" value="{{ $q ?: ($kundennr?:'') }}" placeholder="Kunde, Beschreibung, Nr."></label><div class="actions"><button class="primary">Liste aktualisieren</button></div></form>
<div class="workspace"><section class="card"><div class="card-head"><h2>Aufträge</h2><span class="badge">{{ $auftraege->count() }} Treffer</span></div><div class="list">@forelse($auftraege as $a)<a class="order {{ $selected&&(int)$selected->intAufNr===(int)$a->intAufNr?'selected':'' }}" href="{{ route('fakturierung.index',array_filter(['von'=>$von,'bis'=>$bis,'art'=>$art,'q'=>$q,'auftragsnr'=>$auftragsnr?:null,'kundennr'=>$kundennr?:null,'auftrag'=>$a->intAufNr])) }}"><div class="orderno">#{{ $a->intAufNr }}</div><div><div class="name">{{ $kunden->get($a->intKID)?->strName??('Kunde '.$a->intKID) }}</div><div class="desc">{{ $a->strBeschreibung }}</div></div><div class="date">{{ $a->letztesRechnungsdatum?'zuletzt '.\Carbon\Carbon::parse($a->letztesRechnungsdatum)->format('d.m.Y'):'noch keine Rechnung' }}</div></a>@empty<div class="empty">Keine Aufträge gefunden.</div>@endforelse</div></section>
<section class="card">@if($selected)<div class="card-head"><div><h2>Auftrag #{{ $selected->intAufNr }}</h2><div class="subtitle">{{ $kunden->get($selected->intKID)?->strName??('Kunde '.$selected->intKID) }}</div></div></div><div class="detail"><p><strong>{{ $selected->strBeschreibung }}</strong></p>@if($selected->strAbrechnungshinweis)<p><strong>Abrechnungshinweis:</strong> {{ $selected->strAbrechnungshinweis }}</p>@endif @if($selected->boolEingefroren)<div class="warning"><strong>Achtung:</strong> Auftrag ist eingefroren.</div>@endif @forelse($positionen as $p) @php($b=$berechnet->get($p->intID)) <div class="position"><div class="pos-title">#{{ $p->intID }} · {{ $p->strBeschreibung }}</div><div class="metrics"><span>Menge {{ number_format((float)$p->intMenge,2,',','.') }}</span><span>{{ number_format((float)$p->fEndpreis,2,',','.') }} € netto</span><span>Rabatt {{ number_format((float)$p->fRabattInProzent,2,',','.') }} %</span><span>USt. {{ number_format((float)$p->intMwstsatz,2,',','.') }} %</span><span>Fakt. {{ $p->datFakturierAb?\Carbon\Carbon::parse($p->datFakturierAb)->format('d.m.Y'):'–' }} bis {{ $p->datFakturierBis?\Carbon\Carbon::parse($p->datFakturierBis)->format('d.m.Y'):'–' }}</span><span>{{ $b?$b->anzahl.'× berechnet, zuletzt '.\Carbon\Carbon::parse($b->zuletztBerechnet)->format('d.m.Y'):'noch nie berechnet' }}</span></div></div>@empty<div class="empty">Keine Positionen vorhanden.</div>@endforelse</div>@else<div class="empty"><strong>Auftrag auswählen</strong><br><br>Die Vorschau erscheint hier direkt neben der Liste.</div>@endif</section></div></div></body></html>
